def test_cloud_redis_cluster_base_transport_error():
    # Passing both a credentials object and credentials_file should raise an error
    with pytest.raises(core_exceptions.DuplicateCredentialArgs):
        transport = transports.CloudRedisClusterTransport(
            credentials=ga_credentials.AnonymousCredentials(),
            credentials_file="credentials.json",
        )


def test_cloud_redis_cluster_base_transport():
    # Instantiate the base transport.
    with mock.patch(
        "google.cloud.redis_cluster_v1.services.cloud_redis_cluster.transports.CloudRedisClusterTransport.__init__"
    ) as Transport:
        Transport.return_value = None
        transport = transports.CloudRedisClusterTransport(
            credentials=ga_credentials.AnonymousCredentials(),
        )

    # Every method on the transport should just blindly
    # raise NotImplementedError.
    methods = (
        "list_clusters",
        "list_acl_policies",
        "get_cluster",
        "get_acl_policy",
        "update_cluster",
        "update_acl_policy",
        "delete_cluster",
        "delete_acl_policy",
        "get_acl_policy_revision",
        "list_acl_policy_revisions",
        "create_cluster",
        "create_acl_policy",
        "get_cluster_certificate_authority",
        "get_shared_regional_certificate_authority",
        "reschedule_cluster_maintenance",
        "list_backup_collections",
        "get_backup_collection",
        "list_backups",
        "get_backup",
        "delete_backup",
        "export_backup",
        "backup_cluster",
        "list_token_auth_users",
        "get_token_auth_user",
        "list_auth_tokens",
        "get_auth_token",
        "add_token_auth_user",
        "delete_token_auth_user",
        "add_auth_token",
        "delete_auth_token",
        "get_location",
        "list_locations",
        "get_operation",
        "cancel_operation",
        "delete_operation",
        "list_operations",
    )
    for method in methods:
        with pytest.raises(NotImplementedError):
            getattr(transport, method)(request=object())

    with pytest.raises(NotImplementedError):
        transport.close()

    # Additionally, the LRO client (a property) should
    # also raise NotImplementedError
    with pytest.raises(NotImplementedError):
        transport.operations_client

    # Catch all for all remaining methods and properties
    remainder = [
        "kind",
    ]
    for r in remainder:
        with pytest.raises(NotImplementedError):
            getattr(transport, r)()


def test_cloud_redis_cluster_base_transport_with_credentials_file():
    # Instantiate the base transport with a credentials file
    with (
        mock.patch.object(
            google.auth, "load_credentials_from_file", autospec=True
        ) as load_creds,
        mock.patch(
            "google.cloud.redis_cluster_v1.services.cloud_redis_cluster.transports.CloudRedisClusterTransport._prep_wrapped_messages"
        ) as Transport,
    ):
        Transport.return_value = None
        load_creds.return_value = (ga_credentials.AnonymousCredentials(), None)
        transport = transports.CloudRedisClusterTransport(
            credentials_file="credentials.json",
            quota_project_id="octopus",
        )
        load_creds.assert_called_once_with(
            "credentials.json",
            scopes=None,
            default_scopes=("https://www.googleapis.com/auth/cloud-platform",),
            quota_project_id="octopus",
        )


