@pytest.mark.parametrize(
    "transport_name",
    [
        "rest",
    ],
)
def test_cloud_redis_cluster_client_transport_session_collision(transport_name):
    creds1 = ga_credentials.AnonymousCredentials()
    creds2 = ga_credentials.AnonymousCredentials()
    client1 = CloudRedisClusterClient(
        credentials=creds1,
        transport=transport_name,
    )
    client2 = CloudRedisClusterClient(
        credentials=creds2,
        transport=transport_name,
    )
    session1 = client1.transport.list_clusters._session
    session2 = client2.transport.list_clusters._session
    assert session1 != session2
    session1 = client1.transport.list_acl_policies._session
    session2 = client2.transport.list_acl_policies._session
    assert session1 != session2
    session1 = client1.transport.get_cluster._session
    session2 = client2.transport.get_cluster._session
    assert session1 != session2
    session1 = client1.transport.get_acl_policy._session
    session2 = client2.transport.get_acl_policy._session
    assert session1 != session2
    session1 = client1.transport.update_cluster._session
    session2 = client2.transport.update_cluster._session
    assert session1 != session2
    session1 = client1.transport.update_acl_policy._session
    session2 = client2.transport.update_acl_policy._session
    assert session1 != session2
    session1 = client1.transport.delete_cluster._session
    session2 = client2.transport.delete_cluster._session
    assert session1 != session2
    session1 = client1.transport.delete_acl_policy._session
    session2 = client2.transport.delete_acl_policy._session
    assert session1 != session2
    session1 = client1.transport.get_acl_policy_revision._session
    session2 = client2.transport.get_acl_policy_revision._session
    assert session1 != session2
    session1 = client1.transport.list_acl_policy_revisions._session
    session2 = client2.transport.list_acl_policy_revisions._session
    assert session1 != session2
    session1 = client1.transport.create_cluster._session
    session2 = client2.transport.create_cluster._session
    assert session1 != session2
    session1 = client1.transport.create_acl_policy._session
    session2 = client2.transport.create_acl_policy._session
    assert session1 != session2
    session1 = client1.transport.get_cluster_certificate_authority._session
    session2 = client2.transport.get_cluster_certificate_authority._session
    assert session1 != session2
    session1 = client1.transport.get_shared_regional_certificate_authority._session
    session2 = client2.transport.get_shared_regional_certificate_authority._session
    assert session1 != session2
    session1 = client1.transport.reschedule_cluster_maintenance._session
    session2 = client2.transport.reschedule_cluster_maintenance._session
    assert session1 != session2
    session1 = client1.transport.list_backup_collections._session
    session2 = client2.transport.list_backup_collections._session
    assert session1 != session2
    session1 = client1.transport.get_backup_collection._session
    session2 = client2.transport.get_backup_collection._session
    assert session1 != session2
    session1 = client1.transport.list_backups._session
    session2 = client2.transport.list_backups._session
    assert session1 != session2
    session1 = client1.transport.get_backup._session
    session2 = client2.transport.get_backup._session
    assert session1 != session2
    session1 = client1.transport.delete_backup._session
    session2 = client2.transport.delete_backup._session
    assert session1 != session2
    session1 = client1.transport.export_backup._session
    session2 = client2.transport.export_backup._session
    assert session1 != session2
    session1 = client1.transport.backup_cluster._session
    session2 = client2.transport.backup_cluster._session
    assert session1 != session2
    session1 = client1.transport.list_token_auth_users._session
    session2 = client2.transport.list_token_auth_users._session
    assert session1 != session2
    session1 = client1.transport.get_token_auth_user._session
    session2 = client2.transport.get_token_auth_user._session
    assert session1 != session2
    session1 = client1.transport.list_auth_tokens._session
    session2 = client2.transport.list_auth_tokens._session
    assert session1 != session2
    session1 = client1.transport.get_auth_token._session
    session2 = client2.transport.get_auth_token._session
    assert session1 != session2
    session1 = client1.transport.add_token_auth_user._session
    session2 = client2.transport.add_token_auth_user._session
    assert session1 != session2
    session1 = client1.transport.delete_token_auth_user._session
    session2 = client2.transport.delete_token_auth_user._session
    assert session1 != session2
    session1 = client1.transport.add_auth_token._session
